<?php require dirname(__DIR__).'/app/bootstrap.php';if((int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0){http_response_code(403);exit('Setup already completed.');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$n=trim($_POST['name']??'');$em=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';if(!$n||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<12)$error='Enter a name, valid email and password of at least 12 characters.';else{$q=db()->prepare('INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)');$q->execute([$n,$em,password_hash($pw,PASSWORD_DEFAULT)]);login_admin($em,$pw);redirect(url('admin/index.php'));}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="<?=e(url('assets/css/admin.css'))?>"><title>Initial setup</title></head><body class="login"><form method="post" class="login-card"><?=csrf_field()?><h2>Create first admin</h2><p>Setup locks after the first admin is created.</p><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password (12+ characters)<input type="password" name="password" minlength="12" required></label><button class="primary">Create administrator</button></form></body></html>